["CONFIGURES_EVENT_DRIVEN_AUTOMATION", "PREVENTS_SELF_CAUSED_ADVERSE_EFFECTS_THROUGH_CORRECTIVE_ACTION", "EVALUATES_CANDIDATE_AGAINST_ENUMERATED_CONSTRAINTS_OR_SCENARIOS", "RESOLVES_EVALUATED_CANDIDATE_ELEMENTS_TO_SINGLE_RESULT", "INTERPRETS_REQUIREMENTS_FOR_ACTION_ADMISSIBILITY", "INITIATES_DETACHED_ASYNCHRONOUS_EXECUTION", "REPORTS_ABSENT_OR_UNAVAILABLE_CAPABILITY", "IDENTIFIES_SPECIFIC_POTENTIAL_FAILURE_MODE", "ASSESSES_COMPETING_ACCOUNTS_OF_SAME_OBSERVATION", "ESTABLISHES_EVIDENCE_GROUNDED_TASK_OUTCOME_REFERENCE", "FORMULATES_STRUCTURED_OPERATIVE_ACCOUNT", "SPECIFIES_TARGET_LINKED_CONCRETE_MEANS", "GROUNDS_COMPUTATIONAL_ASSESSMENT_IN_QUANTITATIVE_ANALYSIS", "ANTICIPATES_PROSPECTIVE_VERIFICATION", "DELIMITS_MODIFICATION_AND_RESIDUAL_ARTIFACT_SCOPE", "IDENTIFIES_DEFICIENCY_OR_INCOMPLETENESS", "REPRODUCES_SPECIFIED_PROCEDURE_OR_OPERATION_ORDER", "IMPLEMENTS_LIMITATION_RESPONSIVE_ALTERNATIVE_APPROACH", "EXECUTES_REASONED_REMOVAL_OF_UNWANTED_STATE", "RESOLVES_CANDIDATE_STATUS_FROM_OBSERVED_EVIDENCE", "GROUNDS_REASONING_SPECIFICATION_IN_OBSERVED_ACTION_OR_STATE", "MATERIALIZES_SPECIFIED_CONTENT_IN_DESIGNATED_ARTIFACT", "INTERPRETS_PROBLEMATIC_OBSERVATION_FOR_UNDERSTANDING_OR_RESPONSE", "GROUNDS_CONSTRAINT_OR_JUDGMENT_IN_OBSERVED_EVIDENCE", "CONFIRMS_INTENDED_EFFECT_OR_REQUIRED_STATE_FROM_OBSERVED_RESULT", "PRESERVES_VERIFIED_SUBSTANCE_DURING_REPRESENTATIONAL_REVISION", "CONSTRAINT_DRIVEN_ARTIFACT_ELIMINATION_OR_REVISION", "GENERALIZES_INFERRED_RULE_BEYOND_OBSERVED_EXAMPLES", "RECONSTRUCTS_ANCESTRY_OR_DIVERGENCE_FROM_VERSION_IDENTIFIERS", "INTEGRATES_MULTIPLE_OBSERVATIONS_INTO_UNIFIED_REPRESENTATION", "DIRECTS_INVESTIGATIVE_FOCUS_FROM_OBSERVED_FEATURE", "INTERPRETS_OBSERVED_CONTENT_AS_TYPED_OR_STRUCTURED_INFORMATION", "DERIVES_GOVERNING_ARTIFACT_JUDGMENT_FROM_OBSERVED_CONTENT", "DISCRIMINATES_BENIGN_REFERENCE_OCCURRENCES_FROM_ACTUAL_TARGETS", "RECORDS_DURABLE_ARTIFACT_STATE_REFERENCE_FOR_COMPARISON_OR_HISTORY", "PERSISTS_VALIDATED_STATE_TO_AUTHORITATIVE_STORE", "DERIVES_CONCRETE_TARGET_LOCATION_FROM_OBSERVED_LAYOUT_METADATA", "RESOLVES_TASK_RELEVANT_PREREQUISITE_OR_ENVIRONMENT_STATE", "CONDUCTS_CONCERN_MOTIVATED_EVIDENCE_GATHERING"]

Read every member's complete definition, ordered parameters, assertion conditions, and exclusion conditions. Identify the common underlying behavioral mechanism and generate exactly one complete predicate following the system instructions. The new predicate must preserve the cluster arity. Use a unique predicate name that does not conflict with previously generated predicate names. Return only the complete five-field JSON predicate.

message.content:
{
  "name": "IMPLEMENTS_REASONED_FAILURE_OR_RISK_RESPONSE_WITH_OBSERVED_EVIDENCE",
  "definition": "An evidence-linked failure-risk response mechanism in which reasoning identifies a concrete failure condition—an observed failure and its cause, a specific foreseeable failure mode, or a required capability that must survive interruption—then an action implements a corrective change, preventive mitigation, or guarded recovery mechanism that specifically addresses that condition, and an observation supplies diagnostically relevant failure evidence or confirms the mitigated, restored, or created state.",
  "parameters": [
    {
      "name": "failure_condition_reasoning",
      "type": "reasoning",
      "description": "Reasoning that diagnoses an observed failure and its cause, identifies a specific foreseeable failure mode that could prevent the goal, or establishes that a required capability must survive interruption or restart, thereby determining the needed response."
    },
    {
      "name": "addressing_action",
      "type": "action",
      "description": "Action that implements the specifically reasoned change, preventive measure, or guarded recovery mechanism intended to overcome, avoid, or recover from the identified failure condition rather than merely repeating or ignoring it."
    },
    {
      "name": "evidence_observation",
      "type": "observation",
      "description": "Observation that reports the earlier failure or error, provides evidence consistent with the preventive or recovery measure being in place, or confirms successful creation and usability of the recovery mechanism."
    }
  ],
  "assertion_conditions": [
    "The failure_condition_reasoning identifies a concrete failure condition: a diagnosed cause of an observed failure, a specific anticipated failure mode or pitfall that could prevent the goal, or a requirement that a capability survive interruption or restart.",
    "The addressing_action is informed by that reasoning and changes the relevant parameter, resource, approach, configuration, permission, state, or mechanism to address the identified failure condition.",
    "When the action is claimed as preventive, it is applied before the identified failure occurs and specifically targets that failure mode.",
    "When the action is claimed as guarded recovery, the created mechanism includes a presence check that avoids duplicating or restarting an already-present capability and is designed to fail safely without disruptive output.",
    "The evidence_observation reports the earlier failure or error, or supplies evidence consistent with the preventive measure being applied, the mitigated or restored state, or successful creation and usability of the recovery mechanism."
  ],
  "exclusion_conditions": [
    "The action repeats the failed action without any relevant change or is not based on the diagnosed cause or identified failure mode.",
    "The reasoning only mentions a vague or general risk without naming a specific failure condition and without a corresponding action.",
    "The observation neither reports a failure or error nor provides evidence that the mitigation, restoration, or recovery mechanism was applied or created.",
    "For a claimed guarded recovery, the mechanism unconditionally starts the capability without checking whether it is already present, can fail or emit output that disrupts the invoking context, or is merely a one-time activation with no resilience rationale.",
    "The action addresses the failure only after it occurred when the mechanism is claimed as preventive, or the action is preventive but does not address the specific failure mode identified in the reasoning."
  ]
}

